// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GrowthProduct) predicate.GrowthProduct {
	return predicate.GrowthProduct(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GrowthProduct) predicate.GrowthProduct {
	return predicate.GrowthProduct(sql.NotPredicates(p))
}
